import js from '@eslint/js';
import globals from 'globals';
import sonarjs from 'eslint-plugin-sonarjs';
import security from 'eslint-plugin-security';

export default [
  js.configs.recommended,
  sonarjs.configs.recommended,
  security.configs.recommended,
  {
    ignores: [
      '**/node_modules/**',
      '**/dist/**',
      '**/build/**',
      '**/coverage/**',
      'docs/**'
    ]
  },
  {
    files: ['**/*.js', '**/*.jsx'],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: 'module',
      globals: {
        ...globals.node,
        ...globals.browser,
        ...globals.jest,
      }
    },
    rules: {
      'no-unused-vars': 'warn',
      'sonarjs/cognitive-complexity': ['warn', 15],
      'sonarjs/no-duplicate-string': 'off', // Frequently triggers false positives in tests/configs
    }
  }
];

{
  "$schema": "https://unpkg.com/knip@6/schema-json",
  "workspaces": {
    "backend": {
      "entry": ["server.js", "index.js", "scripts/**/*.js"],
      "project": ["**/*.js"]
    },
    "frontend": {
      "entry": ["src/main.jsx", "index.html"],
      "project": ["src/**/*.{js,jsx}"]
    },
    "worker": {
      "entry": ["index.js"],
      "project": ["**/*.js"]
    }
  },
  "ignore": [
    "docs/**",
    "coverage/**"
  ],
  "ignoreDependencies": [
    "eslint-*",
    "stylelint-*"
  ]
}

