const fs = require('fs');
const path = require('path');
const { Baseline } = require('../models');
const { enqueueBaseline } = require('./queueService');

function normalizeCode(value) {
  return typeof value === 'string' ? value : '';
}

function hasExplicitBaseline(spec = {}) {
  const baseline = spec?.baseline;
  if (!baseline || typeof baseline !== 'object') return false;

  return ['html', 'css', 'js'].some((key) => normalizeCode(baseline[key]).trim().length > 0);
}

function hasMeaningfulFallback(files = {}) {
  const html = normalizeCode(files?.html);
  const css = normalizeCode(files?.css);
  const js = normalizeCode(files?.js);

  if (css.trim().length > 0 || js.trim().length > 0) return true;

  const compactHtml = html.replace(/\s+/g, ' ').trim().toLowerCase();
  if (!compactHtml) return false;
  if (compactHtml.includes('start styling here')) return false;

  return compactHtml.length > 0;
}

function prepareAutoBaselineSpec(spec = {}, fallbackFiles = {}) {
  const nextSpec = spec && typeof spec === 'object' ? { ...spec } : {};

  if (hasExplicitBaseline(nextSpec)) {
    return {
      spec: nextSpec,
      ready: true,
      autoFilled: false
    };
  }

  if (!hasMeaningfulFallback(fallbackFiles)) {
    return {
      spec: nextSpec,
      ready: false,
      autoFilled: false
    };
  }

  nextSpec.baseline = {
    html: normalizeCode(fallbackFiles?.html),
    css: normalizeCode(fallbackFiles?.css),
    js: normalizeCode(fallbackFiles?.js)
  };

  return {
    spec: nextSpec,
    ready: true,
    autoFilled: true
  };
}

async function resolveCurrentBaselineVersion(questionId) {
  const questionIdNum = Number(questionId);
  if (!questionIdNum) return 0;

  const currentMaxDb = await Baseline.max('version', { where: { question_id: questionIdNum } });

  let currentMaxFs = 0;
  try {
    const baseDir = path.resolve(__dirname, '..', '..', '..', 'artifacts', 'baselines', `q${questionIdNum}`);
    if (fs.existsSync(baseDir)) {
      const entries = fs.readdirSync(baseDir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isDirectory()) continue;
        const match = /^v(\d+)$/i.exec(entry.name);
        if (match) currentMaxFs = Math.max(currentMaxFs, Number(match[1]) || 0);
      }
    }
  } catch (_) {
    // Ignore artifact volume read failures.
  }

  return Math.max(Number(currentMaxDb) || 0, currentMaxFs);
}

async function resolveNextBaselineVersion(questionId) {
  const current = await resolveCurrentBaselineVersion(questionId);
  return current + 1;
}

async function queueInitialBaselineIfReady(questionId, spec = {}, fallbackFiles = {}) {
  const prepared = prepareAutoBaselineSpec(spec, fallbackFiles);
  const currentVersion = await resolveCurrentBaselineVersion(questionId);

  if (!prepared.ready || currentVersion > 0) {
    return {
      queued: false,
      version: currentVersion || null,
      jobId: null,
      autoFilled: prepared.autoFilled,
      spec: prepared.spec
    };
  }

  const nextVersion = currentVersion + 1;
  const job = await enqueueBaseline(questionId, nextVersion);

  return {
    queued: true,
    version: nextVersion,
    jobId: job?.id || null,
    autoFilled: prepared.autoFilled,
    spec: prepared.spec
  };
}

module.exports = {
  prepareAutoBaselineSpec,
  resolveCurrentBaselineVersion,
  resolveNextBaselineVersion,
  queueInitialBaselineIfReady
};

const { Queue, QueueEvents } = require('bullmq');
const dotenv = require('dotenv');

dotenv.config();

const connection = {
  host: process.env.REDIS_HOST || '127.0.0.1',
  port: process.env.REDIS_PORT || 6379,
};

// Prevent connecting if we're not running the server to avoid test hang-ups
// Use mocked queue in tests to prevent undefined errors when other routes enqueue jobs
let evaluationQueue;
let queueEvents;

if (process.env.NODE_ENV !== 'test') {
  evaluationQueue = new Queue('evaluation-queue', { connection });
  queueEvents = new QueueEvents('evaluation-queue', { connection });
} else {
  evaluationQueue = {
    add: async () => ({ id: 'mock-job-id' }),
    close: async () => {}
  };
  queueEvents = {
    on: () => {},
    off: () => {},
    close: async () => {}
  };
}

// Export the ability to close the queue connections
const closeQueues = async () => {
  try {
    if (evaluationQueue) {
      await evaluationQueue.close();
    }
    if (queueEvents) {
      await queueEvents.close();
    }
  } catch (e) {
    console.error('Error closing queues', e);
  }
};

const enqueueEvaluation = async (submissionId, runId = null) => {
  const sid = Number(submissionId);
  if (!sid) throw new Error('submissionId is required');

  const payload = { submissionId: sid };
  // If runId is provided, the worker will use that existing EvaluationRun record
  // instead of creating a new one (used for admin replay).
  if (runId != null) payload.runId = Number(runId);

  await evaluationQueue.add('evaluate', payload, {
    // BullMQ rejects purely-numeric custom job ids; prefix with a stable string.
    // Note: BullMQ also disallows ":" in custom ids.
    // For replays we must use a unique id (otherwise BullMQ de-dupes).
    jobId: runId != null ? `replay-${sid}-${runId}` : `submission-${sid}`,
    attempts: 3,
    backoff: { type: 'exponential', delay: 1000 }
  });
};

const enqueueBaseline = async (questionId, version) => {
  const qid = Number(questionId);
  if (!qid) throw new Error('questionId is required');
  const ver = Number(version) || 1;

  const job = await evaluationQueue.add('baseline', { mode: 'baseline', questionId: qid, version: ver }, {
    jobId: `baseline-q${qid}-v${ver}-${Date.now()}`,
    attempts: 1
  });
  return job;
};

module.exports = {
  evaluationQueue,
  queueEvents,
  closeQueues,
  enqueueEvaluation,
  enqueueBaseline
};

const { HTMLHint } = require('htmlhint');
const stylelint = require('stylelint');
const espree = require('espree');
const eslintPkg = require('eslint');
const { Linter } = eslintPkg;

class StaticValidationService {
  async validateSetup(htmlCode, cssCode, jsCode) {
    const results = {
      html: [],
      css: [],
      js: [],
      summary: {
        html: { errors: 0, warnings: 0 },
        css: { errors: 0, warnings: 0 },
        js: { errors: 0, warnings: 0 },
        totalErrors: 0,
        totalWarnings: 0
      },
      isValid: true // Critically invalid syntax will set this to false
    };

    // 1. Validate HTML
    if (htmlCode) {
      const htmlErrors = HTMLHint.verify(htmlCode, {
        'tagname-lowercase': true,
        'attr-lowercase': true,
        'attr-value-double-quotes': true,
        'tag-pair': true,
        'spec-char-escape': true,
        'id-unique': true,
        'src-not-empty': true,
        'title-require': true,
        'alt-require': true
      });
      results.html = htmlErrors.map(e => ({
        line: e.line,
        col: e.col,
        message: e.message,
        type: e.type, // 'error' or 'warning'
        ruleId: e.rule?.id || null
      }));
      // We consider HTML tag pairs missing as critical
      if (htmlErrors.some(e => e.rule.id === 'tag-pair' && e.type === 'error')) {
        results.isValid = false;
      }
      results.summary.html.errors = htmlErrors.filter(e => e.type === 'error').length;
      results.summary.html.warnings = htmlErrors.filter(e => e.type === 'warning').length;
    }

    // 2. Validate CSS
    if (cssCode) {
      try {
        const cssResult = await stylelint.lint({
          code: cssCode,
          config: {
            extends: 'stylelint-config-standard'
          }
        });

        const warnings = cssResult?.results?.[0]?.warnings || [];
        results.css = warnings.map(w => ({
          line: w.line,
          col: w.column,
          message: w.text,
          type: w.severity, // 'error' or 'warning'
          ruleId: w.rule || null
        }));

        results.summary.css.errors = warnings.filter(w => w.severity === 'error').length;
        results.summary.css.warnings = warnings.filter(w => w.severity === 'warning').length;

        // CSS parse errors should fail fast.
        if (warnings.some(w => w.rule === 'CssSyntaxError' || String(w.text || '').includes('CssSyntaxError'))) {
          results.isValid = false;
        }
      } catch (err) {
        results.css.push({ message: err.message, type: 'error', ruleId: 'stylelint' });
        results.summary.css.errors += 1;
        results.isValid = false;
      }
    }

    // 3. Validate JS
    if (jsCode) {
      try {
        // First: syntax validation (fast fail).
        espree.parse(jsCode, { ecmaVersion: 'latest', sourceType: 'script' });

        // Then: quality lint rules using ESLint Linter (no external config files needed).
        if (typeof Linter === 'function') {
          const linter = new Linter();
          const messages = linter.verify(
            jsCode,
            {
              // ESLint (v9+) Linter.verify expects flat-config shape.
              languageOptions: {
                ecmaVersion: 'latest',
                sourceType: 'script',
                // Browser globals to avoid false-positive no-undef for DOM code.
                globals: {
                  window: 'readonly',
                  document: 'readonly',
                  alert: 'readonly',
                  console: 'readonly',
                  navigator: 'readonly',
                  location: 'readonly',
                  fetch: 'readonly',
                  setTimeout: 'readonly',
                  clearTimeout: 'readonly',
                  setInterval: 'readonly',
                  clearInterval: 'readonly',
                  requestAnimationFrame: 'readonly',
                  cancelAnimationFrame: 'readonly'
                }
              },
              rules: {
                'no-undef': 'error',
                'no-unused-vars': ['warn', { vars: 'all', args: 'after-used', ignoreRestSiblings: true }],
                'no-unreachable': 'error',
                'no-extra-semi': 'warn',
                'eqeqeq': 'warn'
              }
            },
            { filename: 'index.js' }
          );

          results.js = messages.map(m => ({
            line: m.line,
            col: m.column,
            message: m.message,
            type: m.severity === 2 ? 'error' : 'warning',
            ruleId: m.ruleId || null
          }));
          results.summary.js.errors = results.js.filter(x => x.type === 'error').length;
          results.summary.js.warnings = results.js.filter(x => x.type === 'warning').length;
        }
      } catch (err) {
        results.js.push({
          line: err.lineNumber,
          col: err.column,
          message: err.message,
          type: 'error',
          ruleId: err.code || 'parse-error'
        });
        results.summary.js.errors += 1;
        results.isValid = false;
      }
    }

    results.summary.totalErrors =
      results.summary.html.errors + results.summary.css.errors + results.summary.js.errors;
    results.summary.totalWarnings =
      results.summary.html.warnings + results.summary.css.warnings + results.summary.js.warnings;

    return results;
  }
}

