            ? 'Builder Mode'
            : 'Foundation Mode';

    return {
      orderedQuestions,
      orderedSubmissions,
      totalQuestions,
      completedCount,
      progressPercent,
      nextQuestion,
      latestSubmission,
      latestScore,
      avgScore,
      bestScore,
