            aiFeedback: {
              summary: "Your JavaScript logic is perfect and HTML structure is mostly correct. However, your CSS layout completely missed the flexbox requirement, causing a large visual diff deviation.",
              suggestions: ["Add 'display: flex' and 'align-items: center' to your main .card class.", "Ensure the button hover transition matches exactly 0.2s duration.", "Your image border radius is slightly off (expected 50%, actual 8px)."],
              difficulty_estimate: "Easy",
              high_diff_cause: "Flexbox layout completely missing on parent container."
            }
          });
          setLoading(false);
          return;
        }

        const qs = activeRunId ? `?run_id=${encodeURIComponent(String(activeRunId))}` : '';
        const res = await fetch(`/api/submissions/${id}/result${qs}`);
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || 'Failed to fetch evaluation result');

        setResult(data);
        setError(null);

        if (data.status === 'completed' || data.status === 'failed') {
          stop();
        }
      } catch (err) {
        console.error(err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    // Poll every 2 seconds until the run completes/fails
    fetchResult();
    intervalId = setInterval(() => {
      if (!stopped) fetchResult();
    }, 2000);

    // Optional: stream progress stages while polling for final artifacts.
    if (id !== 'demo-123') {
      try {
        eventSource = new EventSource(`/api/submissions/${id}/progress`);
        eventSource.onmessage = (e) => {
          try {
            const msg = JSON.parse(e.data);
            if (msg?.progress?.stage) setProgressStage(msg.progress.stage);
          } catch (_) {}
        };
        eventSource.onerror = () => {
          // If SSE fails (proxy/CORS), polling still works.
          if (eventSource) eventSource.close();
          eventSource = null;
        };
      } catch (_) {}
    }

    return () => stop();
  }, [id, activeRunId]);

  const replayEvaluation = async () => {
    if (!id || id === 'demo-123') return;
    setReplayBusy(true);
    setError(null);
    setLoading(true);
    setResult(null);
    setProgressStage('Packaging submission');

    try {
      const res = await fetch(`/api/submissions/${id}/replay`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': String(userId),
          'x-user-role': 'admin'
        }
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to replay evaluation');
      setActiveRunId(data.run_id || null);
    } catch (e) {
      setError(e.message);
      setLoading(false);
    } finally {
      setReplayBusy(false);
    }
  };

  const scores = result?.scores || { html: 0, css: 0, js: 0, visual: 0 };
  const rubric = result?.rubric || { html: 20, css: 35, js: 35, visual: 10, a11y: 0, quality: 0 };
  const totalScore =
    result?.total_score ?? (scores.html + scores.css + scores.js + scores.visual);
  const visual = result?.visualArtifacts || null;
  const mismatchPercent = Number(result?.mismatchPercentage ?? result?.mismatchPercent ?? 0);
  const failedTests = result?.failedTests || [];
  const aiFeedback = result?.aiFeedback || { summary: "No AI feedback generated.", suggestions: [] };

  const visualTests = Array.isArray(result?.visualTests) ? result.visualTests : [];
  const viewportsToRender = visualTests.length > 0
    ? visualTests
    : (visual
        ? [{
            viewport: 'desktop',
            expected: visual.expected || '',
            actual: visual.actual || '',
            diff: visual.diff || '',
            diffPercent: mismatchPercent,
            boxes: visual.boxes || []
          }]
        : []);

  useEffect(() => {
    if (viewportsToRender.length === 0) {
      if (selectedViewport) setSelectedViewport('');
      return;
    }

    const hasCurrent = viewportsToRender.some((vt) => String(vt?.viewport || '') === selectedViewport);
    if (hasCurrent) return;

    const preferredViewport = viewportsToRender.find((vt) => String(vt?.viewport || '').toLowerCase() === 'desktop')?.viewport
      || viewportsToRender[0]?.viewport
      || '';

    setSelectedViewport(String(preferredViewport));
  }, [viewportsToRender, selectedViewport]);

  if (loading) {
    return <div className="h-full flex items-center justify-center"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-600"></div></div>;
  }

  if (error || !result) {
    return (
      <div className="h-full flex flex-col items-center justify-center gap-4 text-center">
        <h2 className="text-2xl font-bold text-gray-900">Evaluation Error</h2>
        <p className="text-gray-500">{error || "Could not load evaluation report."}</p>
        <Link to="/student" className="px-6 py-2 bg-emerald-600 text-white rounded-lg">Return to Workspace</Link>
      </div>
    );
  }

  const activeVisualTest = viewportsToRender.find((vt) => String(vt?.viewport || '') === selectedViewport) || viewportsToRender[0] || null;

  return (
    <div className="max-w-6xl mx-auto h-full flex flex-col gap-6 pb-12">

      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Link to="/student" className="text-gray-400 hover:text-emerald-600 transition-colors">
              <ArrowLeft size={20} />
            </Link>
            <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Evaluation Report</h1>
          </div>
          <p className="text-sm text-gray-500 font-mono ml-7">ID: {result.submission_id}</p>
          {(result.status === 'running' || result.status === 'pending') && (
            <p className="text-xs text-gray-500 ml-7 mt-1">
              <span className="inline-block w-2 h-2 rounded-full bg-emerald-500 animate-pulse mr-2" />
              {progressStage ? `Stage: ${progressStage}` : 'Evaluating...'}
            </p>
          )}
        </div>
        <div className="flex gap-3 w-full sm:w-auto ml-7 sm:ml-0">
          <button
            onClick={() => {
              const runId = result?.run_id;
              if (!id || !runId) return;
              const url = `/api/submissions/${encodeURIComponent(String(id))}/artifacts/report.pdf?run_id=${encodeURIComponent(String(runId))}`;
              window.open(url, '_blank', 'noopener,noreferrer');
            }}
            className="flex-1 sm:flex-none justify-center items-center gap-2 px-4 py-2 bg-gray-50 text-gray-700 hover:bg-gray-100 border border-gray-200 rounded-lg text-sm font-semibold transition-colors flex"
            title="Open evaluation PDF report"
          >
            <Download size={16} /> Export PDF
          </button>
          {isAdmin && id && id !== 'demo-123' && (
            <button
              onClick={replayEvaluation}
              disabled={replayBusy}
              className="flex-1 sm:flex-none justify-center items-center gap-2 px-4 py-2 bg-slate-900 hover:bg-slate-800 disabled:opacity-60 disabled:cursor-not-allowed text-white rounded-lg text-sm font-semibold transition-colors flex"
              title="Replay evaluation for this submission"
            >
              <RefreshCw size={16} className={replayBusy ? 'animate-spin' : ''} /> Replay Evaluation
            </button>
          )}
          <Link to="/student" className="flex-1 sm:flex-none justify-center items-center gap-2 px-6 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-semibold transition-all shadow-sm shadow-emerald-600/20 flex">
            Next Challenge <ArrowRight size={16} />
          </Link>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Left Column: Scores & AI */}
        <div className="lg:col-span-4 flex flex-col gap-6">

          {/* Main Score Card */}
          <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 flex flex-col items-center">
             <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest w-full text-center mb-6 border-b border-gray-50 pb-4">Overall Grade</h3>
             <ScoreGauge score={totalScore} size="lg" />

              {/* Sub-scores */}
              <div className="w-full mt-8 space-y-4">
                 <div className="space-y-1">
                   <div className="flex justify-between text-xs font-semibold text-gray-600">
                     <span>HTML</span> <span>{scores.html}/{rubric.html}</span>
                   </div>
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                     <div className="h-full bg-blue-500 rounded-full" style={{ width: `${rubric.html > 0 ? Math.min(100, (scores.html / rubric.html) * 100) : 0}%` }}></div>
                   </div>
                 </div>
                 <div className="space-y-1">
                   <div className="flex justify-between text-xs font-semibold text-gray-600">
                     <span>CSS</span> <span>{scores.css}/{rubric.css}</span>
                   </div>
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                     <div className="h-full bg-pink-500 rounded-full" style={{ width: `${rubric.css > 0 ? Math.min(100, (scores.css / rubric.css) * 100) : 0}%` }}></div>
                   </div>
                 </div>
                 <div className="space-y-1">
                   <div className="flex justify-between text-xs font-semibold text-gray-600">
                     <span>JavaScript</span> <span>{scores.js}/{rubric.js}</span>
                   </div>
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                     <div className="h-full bg-yellow-500 rounded-full" style={{ width: `${rubric.js > 0 ? Math.min(100, (scores.js / rubric.js) * 100) : 0}%` }}></div>
                   </div>
                 </div>
                 <div className="space-y-1">
                   <div className="flex justify-between text-xs font-semibold text-gray-600">
                     <span>Visual Match</span> <span>{scores.visual}/{rubric.visual}</span>
                   </div>
                   <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                     <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${rubric.visual > 0 ? Math.min(100, (scores.visual / rubric.visual) * 100) : 0}%` }}></div>
                   </div>
                 </div>
              </div>
          </div>

          <AIFeedbackCard feedback={aiFeedback} />

        </div>

        {/* Right Column: Diff & Tests */}
        <div className="lg:col-span-8 flex flex-col gap-6">

           {viewportsToRender.length === 0 ? (
             <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-10 text-center text-gray-500">
               Evaluation artifacts not generated yet.
             </div>
           ) : (
             <div className="flex flex-col gap-3">
               <div className="flex flex-wrap items-center justify-between gap-3 px-1">
                 <div className="text-xs font-black uppercase tracking-widest text-gray-400">
                   Viewport: <span className="text-gray-700">{activeVisualTest?.viewport || 'default'}</span>
                 </div>

                 {viewportsToRender.length > 1 && (
                   <div className="flex flex-wrap items-center gap-2">
                     {viewportsToRender.map((vt) => {
                       const isActive = String(vt?.viewport || '') === String(activeVisualTest?.viewport || '');
                       return (
                         <button
                           key={`viewport-${vt?.viewport || 'default'}`}
                           type="button"
                           onClick={() => setSelectedViewport(String(vt?.viewport || 'default'))}
                           className={`rounded-full px-3 py-1.5 text-xs font-semibold transition ${
                             isActive
                               ? 'bg-emerald-600 text-white shadow-sm'
                               : 'border border-gray-200 bg-white text-gray-600 hover:bg-gray-50'
                           }`}
                         >
                           {vt?.viewport || 'default'}
                         </button>
                       );
                     })}
                   </div>
                 )}
               </div>

               <DiffViewer
                 key={`submission-${result?.submission_id || id}-run-${result?.run_id || 'latest'}-viewport-${activeVisualTest?.viewport || 'default'}`}
                 expectedUrl={activeVisualTest?.expected || ''}
                 actualUrl={activeVisualTest?.actual || ''}
                 diffUrl={activeVisualTest?.diff || ''}
                 expectedRenderUrl={activeVisualTest?.expectedRenderUrl || ''}
                 actualRenderUrl={activeVisualTest?.actualRenderUrl || ''}
                 mismatchPercentage={Number(activeVisualTest?.diffPercent ?? activeVisualTest?.diffPercentage ?? mismatchPercent ?? 0)}
                 boxes={Array.isArray(activeVisualTest?.boxes || activeVisualTest?.hotspots) ? (activeVisualTest?.boxes || activeVisualTest?.hotspots) : []}
                 comparisonWidth={Number(activeVisualTest?.comparisonWidth ?? 0)}
                 comparisonHeight={Number(activeVisualTest?.comparisonHeight ?? 0)}
                 viewportWidth={Number(activeVisualTest?.viewportWidth ?? 0)}
                 viewportHeight={Number(activeVisualTest?.viewportHeight ?? 0)}
               />
             </div>
           )}

           <FailedTestsTable failedTests={failedTests} />

         </div>

       </div>

    </div>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { SaveAll, Layout, Code2, ShieldAlert, Cpu, Plus, Trash2, Settings2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { useToast } from '../components/ui/use-toast';

const TABS = [
  { id: 'general', label: 'General', icon: Layout },
  { icon: Code2, id: 'code', label: 'Starter Code' },
  { icon: ShieldAlert, id: 'constraints', label: 'Constraints' },
  { icon: Cpu, id: 'tests', label: 'Test Specs' }
];

const DEFAULT_FILES = {
  html: "<div class='card'>\n  <!-- Start styling here -->\n</div>",
  css: '',
  js: ''
};

export default function QuestionEditor() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { toast } = useToast();

  const questionId = id ? Number(id) : null;
  const isEdit = Number.isFinite(questionId) && questionId > 0;

  const [activeTab, setActiveTab] = useState('general');
  const [loading, setLoading] = useState(!!isEdit);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const lastSavedAtRef = useRef(null);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [allowedLibraries, setAllowedLibraries] = useState([]);
  const [files, setFiles] = useState(DEFAULT_FILES);
  const [constraints, setConstraints] = useState([]);
  const [specJsonText, setSpecJsonText] = useState('');

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      if (!isEdit) {
        setLoading(false);
        return;
      }
      setLoading(true);
      try {
        const res = await fetch(`/api/questions/${questionId}`);
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Failed to load question');
        if (cancelled) return;

        const q = data.question || {};
        setTitle(q.title || '');
        setDescription(q.description || '');
        setAllowedLibraries(Array.isArray(q.allowed_libraries) ? q.allowed_libraries : []);
        setConstraints(Array.isArray(q.constraints) ? q.constraints : []);

        const byType = new Map((Array.isArray(data.files) ? data.files : []).map((f) => [f.type, f]));
        setFiles({
          html: byType.get('html')?.content ?? DEFAULT_FILES.html,
          css: byType.get('css')?.content ?? DEFAULT_FILES.css,
          js: byType.get('js')?.content ?? DEFAULT_FILES.js
        });

        setSpecJsonText(JSON.stringify(data.testSpec || {}, null, 2));
        setDirty(false);
      } catch (e) {
        toast({ title: 'Load Failed', description: e?.message || 'Could not load question.', variant: 'destructive' });
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    load();
    return () => {
      cancelled = true;
    };
  }, [isEdit, questionId, toast]);

  const canSave = useMemo(() => {
    return !saving && title.trim().length > 0;
  }, [saving, title]);

  const save = async () => {
    if (!canSave) return;
    setSaving(true);
    try {
      let spec_json = null;
      const raw = specJsonText.trim();
      if (raw) {
        try {
          spec_json = JSON.parse(raw);
        } catch (e) {
          throw new Error('Test Specs must be valid JSON.');
        }
      }

      const payload = {
        title: title.trim(),
        description,
        allowed_libraries: allowedLibraries,
        constraints,
        files,
        spec_json
      };

      if (isEdit) {
        const res = await fetch(`/api/questions/${questionId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Save failed');
        if (data?.baseline?.queued) {
          toast({
            title: 'Baseline Queued',
            description: `Visual artifacts for this question were queued automatically as baseline v${data.baseline.version}.`
          });
        }
      } else {
        const res = await fetch(`/api/questions`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok) throw new Error(data.error || 'Create failed');
        const newId = data?.question?.id;
        toast({
          title: data?.baseline?.queued ? 'Created & Queued' : 'Created',
          description: data?.baseline?.queued
            ? `Question ${newId} created. Baseline v${data.baseline.version} is generating now.`
            : `Question ${newId} created.`
        });
        navigate(`/teacher/editor/${newId}`);
      }

      lastSavedAtRef.current = new Date();
      setDirty(false);
      toast({ title: 'Saved', description: 'Your changes have been saved.' });
    } catch (e) {
      toast({ title: 'Save Failed', description: e?.message || 'Could not save changes.', variant: 'destructive' });
    } finally {
      setSaving(false);
    }
  };

  // Lightweight autosave for edits only.
  useEffect(() => {
    if (!isEdit) return;
    if (!dirty) return;
    const t = setTimeout(() => {
      save();
    }, 2000);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dirty, isEdit]);

  const addConstraint = () => {
    setConstraints((prev) => [...prev, { type: 'css', property: '', value: '', selector: '' }]);
    setDirty(true);
  };

  const removeConstraint = (idx) => {
    setConstraints((prev) => prev.filter((_, i) => i !== idx));
    setDirty(true);
  };

  const updateConstraint = (idx, patch) => {
    setConstraints((prev) => prev.map((c, i) => (i === idx ? { ...c, ...patch } : c)));
    setDirty(true);
  };

  const addLibrary = () => {
    const url = prompt('Enter a CDN URL to allow for this question:');
    if (!url) return;
    setAllowedLibraries((prev) => [...prev, url]);
    setDirty(true);
  };

  const removeLibrary = (idx) => {
    setAllowedLibraries((prev) => prev.filter((_, i) => i !== idx));
    setDirty(true);
  };

  const setFile = (key, value) => {
    setFiles((prev) => ({ ...prev, [key]: value }));
    setDirty(true);
  };

  if (loading) {
    return (
      <div className="max-w-6xl mx-auto py-10 px-6">
        <div className="h-10 w-56 bg-gray-100 rounded-xl animate-pulse" />
        <div className="mt-6 h-[520px] bg-gray-100 rounded-[2.5rem] animate-pulse" />
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto py-8 px-6">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tight">Question Editor</h1>
          <p className="text-gray-500 font-medium">Create and maintain frontend challenges</p>
        </div>
        <div className="flex items-center gap-6">
          <div className="flex items-center gap-2 text-emerald-700 font-bold text-xs bg-emerald-50 px-3 py-1.5 rounded-full">
            <div className={`w-1.5 h-1.5 rounded-full ${dirty ? 'bg-amber-500' : 'bg-emerald-500'} ${saving ? 'animate-pulse' : ''}`} />
            {saving ? 'Saving...' : dirty ? 'Unsaved changes' : 'Saved'}
          </div>
          <div className="flex gap-3">
            <button
              onClick={() => navigate('/teacher')}
              className="px-5 py-2.5 rounded-xl border-2 border-gray-100 text-gray-600 font-bold hover:bg-gray-50 transition-all flex items-center gap-2 text-sm"
            >
              Cancel
            </button>
            <button
              onClick={save}
              disabled={!canSave}
              className="px-5 py-2.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 disabled:cursor-not-allowed text-white font-bold shadow-lg shadow-emerald-100 transition-all flex items-center gap-2 text-sm"
            >
              <SaveAll size={18} /> Save Challenge
            </button>
          </div>
        </div>
      </div>

      <div className="flex gap-8">
        <aside className="w-64 space-y-1">
          {TABS.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-2xl font-bold transition-all ${
                activeTab === tab.id
                  ? 'bg-white text-emerald-600 shadow-sm border border-gray-100'
                  : 'text-gray-400 hover:text-gray-600 hover:bg-gray-50'
              }`}
            >
              <tab.icon size={20} />
              {tab.label}
            </button>
          ))}
        </aside>

        <main className="flex-1 bg-white border border-gray-100 rounded-[2.5rem] shadow-sm p-8 min-h-[600px]">
          <AnimatePresence mode="wait">
            {activeTab === 'general' && (
              <motion.div
                key="general"
                initial={{ opacity: 0, x: 10 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -10 }}
                className="space-y-6"
              >
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-wide">Challenge Title</label>
                  <input
                    type="text"
                    value={title}
                    onChange={(e) => { setTitle(e.target.value); setDirty(true); }}
                    placeholder="e.g. Build a Product Grid with Grid Layout"
                    className="w-full px-4 py-3 rounded-2xl border-2 border-gray-50 focus:border-emerald-100 outline-none transition-all placeholder:text-gray-300 font-medium text-lg"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-wide">Detailed Briefing</label>
                  <textarea
                    rows={8}
                    value={description}
                    onChange={(e) => { setDescription(e.target.value); setDirty(true); }}
                    placeholder="Describe the objective, expected behavior, and specific requirements..."
                    className="w-full px-4 py-3 rounded-2xl border-2 border-gray-50 focus:border-emerald-100 outline-none transition-all placeholder:text-gray-300 font-medium leading-relaxed"
                  />
                </div>

                <div className="flex items-center justify-between">
                  <div className="text-sm font-bold text-gray-900 flex items-center gap-2">
                    <Settings2 size={18} className="text-emerald-600" /> Allowed Libraries
                  </div>
                  <button onClick={addLibrary} className="text-emerald-600 font-bold flex items-center gap-1 hover:underline">
                    <Plus size={18} /> Add Library
                  </button>
                </div>
                <div className="space-y-2">
                  {allowedLibraries.map((l, idx) => (
                    <div key={`${l}-${idx}`} className="flex items-center justify-between gap-3 p-3 rounded-2xl bg-gray-50 border border-gray-100">
                      <div className="font-mono text-xs text-gray-700 truncate">{l}</div>
                      <button onClick={() => removeLibrary(idx)} className="p-2 text-gray-400 hover:text-red-600 transition-colors" aria-label="Remove library">
                        <Trash2 size={18} />
                      </button>
                    </div>
                  ))}
                  {allowedLibraries.length === 0 && (
                    <div className="py-8 text-center border-2 border-dashed border-gray-100 rounded-3xl text-gray-400 font-medium">
                      No libraries allowed. (Default: fully offline sandbox)
                    </div>
                  )}
                </div>
              </motion.div>
            )}

            {activeTab === 'code' && (
              <motion.div
                key="code"
                initial={{ opacity: 0, x: 10 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -10 }}
                className="space-y-6"
              >
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest">index.html</label>
                    <textarea
                      value={files.html}
                      onChange={(e) => setFile('html', e.target.value)}
                      className="w-full h-60 rounded-2xl bg-gray-900 text-emerald-300 p-4 font-mono text-xs shadow-inner outline-none"
