                    />
                  </div>
                </div>
              </motion.div>
            )}

            {activeTab === 'constraints' && (
              <motion.div
                key="constraints"
                initial={{ opacity: 0, x: 10 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -10 }}
                className="space-y-6"
