import * as React from "react"
import {
  Toast,
  ToastClose,
  ToastDescription,
  ToastProvider,
  ToastTitle,
  ToastViewport,
} from "./toast"

const TOAST_LIMIT = 3
const TOAST_REMOVE_DELAY = 10000

let count = 0

function genId() {
  count = (count + 1) % Number.MAX_SAFE_INTEGER
  return count.toString()
}

const toastListeners = new Set()

let memoryState = { toasts: [] }

function dispatch(action) {
  memoryState = reducer(memoryState, action)
  toastListeners.forEach((listener) => {
    listener(memoryState)
  })
}

function reducer(state, action) {
  switch (action.type) {
    case "ADD_TOAST":
      return {
        ...state,
        toasts: [action.toast, ...state.toasts].slice(0, TOAST_LIMIT),
      }

    case "UPDATE_TOAST":
      return {
        ...state,
        toasts: state.toasts.map((t) =>
          t.id === action.toast.id ? { ...t, ...action.toast } : t
        ),
      }

    case "DISMISS_TOAST": {
      const { toastId } = action
      if (toastId) {
        return {
          ...state,
          toasts: state.toasts.map((t) =>
            t.id === toastId || toastId === undefined
              ? { ...t, open: false }
              : t
          ),
        }
      }
      return {
        ...state,
        toasts: state.toasts.map((t) => ({ ...t, open: false })),
      }
    }
    case "REMOVE_TOAST":
      if (action.toastId === undefined) {
        return {
          ...state,
          toasts: [],
        }
      }
      return {
        ...state,
        toasts: state.toasts.filter((t) => t.id !== action.toastId),
      }
  }
}

function toast({ ...props }) {
  const id = genId()

  const update = (props) =>
    dispatch({
      type: "UPDATE_TOAST",
      toast: { ...props, id },
    })
  const dismiss = () => dispatch({ type: "DISMISS_TOAST", toastId: id })

  dispatch({
    type: "ADD_TOAST",
    toast: {
      ...props,
      id,
      open: true,
      onOpenChange: (open) => {
        if (!open) dismiss()
      },
    },
  })

  return {
    id: id,
    dismiss,
    update,
  }
}

function useToast() {
  const [state, setState] = React.useState(memoryState)

  React.useEffect(() => {
    toastListeners.add(setState)
    return () => {
      toastListeners.delete(setState)
    }
  }, [state])

  return {
    ...state,
    toast,
    dismiss: (toastId) => dispatch({ type: "DISMISS_TOAST", toastId }),
  }
}

function Toaster() {
  const { toasts } = useToast()

  return (
    <ToastProvider>
      {toasts.map(function ({ id, title, description, action, ...props }) {
        return (
          <Toast key={id} {...props}>
            <div className="grid gap-1">
              {title && <ToastTitle>{title}</ToastTitle>}
              {description && (
                <ToastDescription>{description}</ToastDescription>
              )}
            </div>
            {action}
            <ToastClose />
          </Toast>
        )
      })}
      <ToastViewport />
    </ToastProvider>
  )
}

export function dispatchForTest(action) {
  if (process.env.NODE_ENV === 'test') {
    dispatch(action)
  }
}

export { useToast, toast, Toaster }

import React from 'react';
import Editor from '@monaco-editor/react';

export default function CodeEditor({ language, value, onChange, readOnly = false }) {
  const handleEditorDidMount = (editor, monaco) => {
    // Custom theme for the editor to match our SaaS palette
    monaco.editor.defineTheme('saasDark', {
      base: 'vs-dark',
      inherit: true,
      rules: [
        { background: '0f172a' }
      ],
      colors: {
        'editor.background': '#0f172a',
        'editor.lineHighlightBackground': '#1e293b',
      }
    });
    monaco.editor.setTheme('saasDark');

    // Add quick formatting shortcut
    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyMod.Shift | monaco.KeyCode.KeyF, () => {
      editor.getAction('editor.action.formatDocument').run();
    });
  };

  return (
    <div className="w-full h-full rounded-b-xl overflow-hidden border-t border-slate-800">
      <Editor
        height="100%"
        language={language}
        value={value}
        onChange={onChange}
        theme="vs-dark" // Fallback, onMount will set our custom 'saasDark' theme
        onMount={handleEditorDidMount}
        options={{
          minimap: { enabled: false },
          fontSize: 14,
          fontFamily: 'JetBrains Mono, monospace',
          wordWrap: 'on',
          lineNumbersMinChars: 3,
          padding: { top: 16, bottom: 16 },
          scrollBeyondLastLine: false,
          smoothScrolling: true,
          readOnly: readOnly,
          formatOnPaste: true,
        }}
        loading={
          <div className="flex h-full items-center justify-center bg-slate-900 text-slate-400">
             <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-emerald-500"></div>
          </div>
        }
      />
    </div>
  );
}

import React, { useEffect, useRef } from 'react';
import { buildPreviewDocument } from './previewDocument';

export default function PreviewFrame({ html, css, js }) {
  const iframeRef = useRef(null);

  useEffect(() => {
    if (!iframeRef.current) return;

    const content = buildPreviewDocument({ html, css, js });

    const blob = new Blob([content], { type: 'text/html' });
    const url = URL.createObjectURL(blob);

    iframeRef.current.src = url;

    return () => {
      URL.revokeObjectURL(url);
    };
  }, [html, css, js]);

  return (
    <div className="w-full h-full bg-white rounded-b-xl overflow-hidden border-t border-gray-100 flex flex-col relative">
      <div className="flex bg-gray-50 border-b border-gray-200 px-3 py-1.5 items-center justify-between text-xs text-gray-500 font-mono select-none shadow-sm z-10">
        <div className="flex gap-1.5 items-center">
            <span className="w-2.5 h-2.5 rounded-full bg-red-400"></span>
            <span className="w-2.5 h-2.5 rounded-full bg-amber-400"></span>
            <span className="w-2.5 h-2.5 rounded-full bg-green-400"></span>
        </div>
        <span>Browser Preview</span>
      </div>
      <iframe
        ref={iframeRef}
        sandbox="allow-scripts allow-modals"
        title="Live Preview"
        className="flex-1 w-full bg-white"
        frameBorder="0"
      />
    </div>
  );
}

import React from 'react';
import DOMPurify from 'dompurify';

export default function QuestionPanel({ question }) {
  if (!question) {
    return (
      <div className="h-full flex items-center justify-center text-gray-400">
        Loading question...
      </div>
    );
  }

  return (
    <div className="w-full h-full bg-white overflow-y-auto px-6 py-8">
      <div className="flex items-center gap-3 mb-6">
        <span className="px-2.5 py-1 bg-emerald-100 text-emerald-700 font-semibold text-xs rounded-md shadow-sm">
          {question.difficulty || 'Easy'}
        </span>
        <h1 className="text-2xl font-bold text-gray-900 tracking-tight">{question.title}</h1>
      </div>

      <div className="prose prose-indigo max-w-none prose-sm sm:prose-base text-gray-700">
        <div dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(question.description) }} />
      </div>

      {question.requirements && question.requirements.length > 0 && (
        <div className="mt-10">
          <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wider mb-4 border-b border-gray-100 pb-2">Technical Requirements</h3>
          <ul className="space-y-3">
            {question.requirements.map((req, idx) => (
              <li key={idx} className="flex gap-3 text-sm text-gray-700">
                <span className="text-emerald-500 mt-0.5">•</span>
                <span>{req}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export function buildPreviewDocument({ html = '', css = '', js = '' } = {}) {
  // Keep this document minimal and deterministic so preview behaves consistently.
  // Student code is executed inside the iframe/new tab just like the in-page preview.
  return `<!DOCTYPE html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Amypo Preview</title>
    <style>
${css}
    </style>
  </head>
  <body>
${html}
    <script>
      try {
${js}
      } catch (error) {
        console.error('Runtime Error:', error);
      }
    </script>
  </body>
</html>`;
}
